#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    using namespace std;
    unsigned N, K;
    cin >> N >> K;
    vector<vector<unsigned>> edges(N);
    for(unsigned i{1}; i < N; ++i){
        unsigned A, B;
        cin >> A >> B;
        edges[--A].emplace_back(--B);
        edges[B].emplace_back(A);
    }

    // use[i] := 答えとなる木で頂点 i を使う
    vector<bool> use(N);
    // 木 DP をするための根
    unsigned root;
    cin >> root;
    --root;
    use[root] = true;
    for(unsigned i{1}; i < K; ++i){
        unsigned V;
        cin >> V;
        use[--V] = true;
    }

    // 木 DP を行う
    // dfs(now, prev) := prev を親とした now 以下の部分木に使う頂点があるか
    [dfs{[&edges, &use](const auto& f, unsigned now, unsigned prev) -> bool {
        for(const auto next : edges[now])
            if (next != prev)
                use[now] = use[now] | f(f, next, now);
        return use[now];
    }}](unsigned v){
        dfs(dfs, v, v);
    }(root); // 使う頂点を根として木 DP

    cout << ranges::count(use, true) << endl;
    return 0;
}
